a_flank(CLK := a_givare);
b_flank(CLK := b_givare);
IF kor AND NOT nodstopp THEN
    CASE a_laget OF
    0:
        IF a_flank.Q THEN
            a_laget := 1;
        END_IF;
    1:
        a_stopp := TRUE;
        a_tid(IN := TRUE, PT := T#2s);
