            a_laget := 2;
        END_IF;
    2:
        a_stopp := FALSE;
        a_tid(IN := FALSE, PT := T#2s);
        a_slapp := (NOT b_slapp) OR a_slapp;
        a_utid(IN := a_slapp, PT := T#1s);
        IF a_utid.Q THEN
            a_laget := 3;
        END_IF;
    3:
        a_slapp := FALSE;
        a_utid(IN := FALSE, PT := T#1s);
        a_laget := 0;
    END_CASE;

    CASE b_laget OF
    0:
        IF b_flank.Q THEN
            b_laget := 1;
        END_IF;
    1:
        b_stopp := TRUE;
        b_tid(IN := TRUE, PT := T#2s);
        IF b_tid.Q THEN
            b_laget := 2;
        END_IF;
    2:
        b_stopp := FALSE;
        b_tid(IN := FALSE, PT := T#2s);
        b_slapp := (NOT a_slapp) OR b_slapp;
        b_utid(IN := b_slapp, PT := T#1s);
        IF b_utid.Q THEN
            b_laget := 3;
