            a_laget := 2;
        END_IF;
    2:
        IF NOT b_slapp THEN
            a_stopp := FALSE;
            a_utid(IN := TRUE, PT := T#1s);
            IF a_utid.Q THEN
                a_utid(IN := FALSE, PT := T#1s);
                a_laget := 0;
            END_IF;
        END_IF;
    END_CASE;

    b_flank(CLK := b_givare);
    CASE b_laget OF
    0:
        IF b_flank.Q THEN
            b_laget := 1;
        END_IF;
    1:
        b_stopp := TRUE;
