            IF b_utid.Q THEN
                b_utid(IN := FALSE, PT := T#1s);
                b_laget := 0;
            END_IF;
        END_IF;
    END_CASE;

    a_slapp := (a_laget = 2) AND NOT b_slapp;
    b_slapp := (b_laget = 2) AND NOT a_slapp;
END_IF;

IF NOT kor OR nodstopp THEN
    (* line stopped: freeze sequence and outputs, no station may request outfeed *)
ELSE
    a_flank(CLK := a_givare);
    CASE a_laget OF
    0:
        IF a_flank.Q THEN
            a_laget := 1;
        END_IF;
    1:
        a_stopp := TRUE;
        a_tid(IN := TRUE, PT := T#2s);
        IF a_tid.Q THEN
            a_tid(IN := FALSE, PT := T#2s);
            a_laget := 2;
        END_IF;
    2:
        (* wait for the shared outfeed to be free before requesting it *)
        IF NOT b_slapp THEN
            a_slapp := TRUE;
            a_laget := 3;
        END_IF;
    3:
        a_stopp := FALSE;
        a_utid(IN := TRUE, PT := T#1s);
        IF a_utid.Q THEN
            a_slapp := FALSE;
            a_utid(IN := FALSE, PT := T#1s);
            a_laget := 0;
        END_IF;
    END_CASE;

    b_flank(CLK := b_givare);
    CASE b_laget OF
    0:
        IF b_flank.Q THEN
            b_laget := 1;
        END_IF;
    1:
        b_stopp := TRUE;
