        b_slapp := FALSE;
    ELSE
        a_flank(CLK := a_givare);
        CASE a_laget OF
        0:
            IF a_flank.Q THEN
                a_laget := 1;
            END_IF;
        1:
            a_stopp := TRUE;
            a_tid(IN := TRUE, PT := T#2s);
            IF a_tid.Q AND b_laget <> 2 AND NOT b_givare THEN
                a_laget := 2;
            END_IF;
        2:
            a_stopp := FALSE;
            a_slapp := TRUE;
            a_tid(IN := FALSE, PT := T#2s);
            a_utid(IN := TRUE, PT := T#1s);
            IF a_utid.Q THEN
                a_laget := 3;
            END_IF;
        3:
            a_slapp := FALSE;
            a_utid(IN := FALSE, PT := T#1s);
            a_laget := 0;
        END_CASE;
        b_flank(CLK := b_givare);
        CASE b_laget OF
        0:
            IF b_flank.Q THEN
                b_laget := 1;
            END_IF;
        1:
            b_stopp := TRUE;
            b_tid(IN := TRUE, PT := T#2s);
            IF b_tid.Q AND a_laget <> 2 THEN
                b_laget := 2;
            END_IF;
        2:
            b_stopp := FALSE;
            b_slapp := TRUE;
            b_tid(IN := FALSE, PT := T#2s);
            b_utid(IN := TRUE, PT := T#1s);
            IF b_utid.Q THEN
                b_laget := 3;
            END_IF;
        3:
            b_slapp := FALSE;
            b_utid(IN := FALSE, PT := T#1s);
            b_laget := 0;
        END_CASE;
    END_IF;
(* VC_ASSIST KROPP SLUTAR *)
END_PROGRAM
